package com.securevault.service;
import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Service;import java.time.Duration;import java.util.*;
@Service public class AnalyticsCacheService{private final StringRedisTemplate redis;private long hits=0,misses=0,writes=0;public AnalyticsCacheService(StringRedisTemplate r){redis=r;}public synchronized String get(String key){try{String v=redis.opsForValue().get(key);if(v==null)misses++;else hits++;return v;}catch(Exception e){misses++;return null;}}public synchronized void put(String key,String value){try{redis.opsForValue().set(key,value,Duration.ofMinutes(5));writes++;}catch(Exception ignored){}}public synchronized void invalidate(String key){try{redis.delete(key);}catch(Exception ignored){}}public synchronized Map<String,Object> stats(){return Map.of("hits",hits,"misses",misses,"writes",writes,"ttlMinutes",5,"sensitiveDataStored",false,"fallback","database");}}
